import{printedArtwork}from'../../modeling/artwork.js';const front=new URL('./source-vector-front.png',import.meta.url).href,back=new URL('./source-vector-back.png',import.meta.url).href;
/** Matching standard U100 original product-label outlines rasterized;private vectors excluded. */
export function addStickers(host){return[...(printedArtwork(host,{target:host.uwbAssembly.frontCarrier,url:front,size:[17.8,27.8],position:[0,8,3.85],face:'front',depth:.15,name:'UWB front original standard product-label raster',artworkKind:'source-vector-raster'})??[]),...(printedArtwork(host,{target:host.uwbAssembly.backCarrier,url:back,size:[16,28],position:[0,8,-3.9],face:'back',depth:.15,name:'UWB rear original standard product-label raster',artworkKind:'source-vector-raster'})??[])];}
